from pathlib import Path
import json,re
root=Path(__file__).resolve().parents[1]
css=(root/'site/assets/geo.css').read_text()
js=(root/'site/assets/geo.js').read_text()
sample=json.loads((root/'site/assets/sample-report.json').read_text())
comparison=json.loads((root/'site/assets/sample-comparison.json').read_text())
bridge='''document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;const href=a.getAttribute('href')||'';if(href.startsWith('#'))return;if(href.startsWith('/')){e.preventDefault();parent.postMessage({review:href.includes('/run')?'tool':href.includes('/account')||href.includes('/login')?'status':'landing'},'*');}},true);document.querySelectorAll('.choose-plan').forEach(b=>b.onclick=()=>parent.postMessage({review:'status'},'*'));'''
def build(rel,tool=False):
 s=(root/'site'/rel).read_text()
 files=['audit-fonts.css','audit-tool.css'] if tool else ['geo.css']
 for name in files:s=s.replace('<link rel="stylesheet" href="/assets/'+name+'" />','<style>'+(root/'site/assets'/name).read_text()+'</style>').replace('<link rel="stylesheet" href="/assets/'+name+'">','<style>'+(root/'site/assets'/name).read_text()+'</style>')
 s=re.sub(r'<script defer src="/assets/(?:supabase|geo|audit-tool)\.js"></script>','',s)
 localjs=(root/'site/assets/audit-tool.js').read_text() if tool else js
 if tool:
  localjs=localjs.replace("fetch('/assets/sample-report.json',{cache:'no-store'})",'Promise.resolve({ok:true,json:async()=>('+json.dumps(sample)+')})')
  localjs=localjs.replace("fetch('/assets/sample-comparison.json')",'Promise.resolve({ok:true,json:async()=>('+json.dumps(comparison)+')})')
  localjs='window.AEOGEO_OFFLINE_REVIEW=true;'+localjs
  localjs=localjs.replace("async function handleStartAudit(e){e?.preventDefault();", "async function handleStartAudit(e){e?.preventDefault();msg('tool-message','This offline review cannot run live audits. The website installation will connect this exact interface to your account and server.');return;")
 s=s.replace('</body>','<script>'+localjs+'</script><script>'+bridge+'</script></body>')
 return s
landing=build('geo-audit/index.html');tool=build('geo-audit/run/index.html',True)
status='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>'''+css+'''</style><main class="wrap section"><span class="eyebrow">Private build review</span><h1>Built locally.<br><span class="gradient">Not live. Not charging.</span></h1><p class="muted">Your existing website and deployed test accounts remain unchanged.</p><div class="grid3"><section class="card"><h3>Ready to review</h3><p>Product page and pricing. Main-navigation integration in the local website copy. Original supplied pure-tool interface: three stat tiles, 25/75 scope cards, progress checklist/terminal, circular score gauge, four pillar tiles, four report tabs, priority/section filters, page drawer, visible fix templates, checklist simulator, optional saved-report comparison, CSV/Markdown and print/PDF.</p></section><section class="card"><h3>Built, needs connected staging tests</h3><p>Private account/report endpoints, crawl jobs, one-free-audit enforcement, usage/domain limits, draft migration 03, Stripe Checkout/portal and signed subscription webhook scaffolding. No new SQL was applied to your database.</p></section><section class="card"><h3>Still blocks a paid launch</h3><p>Automatic recrawls. Agency teams/client accounts/white-label/API and bulk exports. Confirmed Professional/Agency page allowances. Checkout-session concurrency protection and refund/dispute handling. Stripe and Supabase end-to-end staging tests and approved subscription terms.</p></section></div><div class="notice section-spacer">Prices retained: Starter $49, Professional $149, Agency $499 per month. Annual billing saves 20%. No automatic overages. No testimonials were fabricated.</div><h2>About this review file</h2><p class="muted">The audit dashboard now uses the original layout supplied by the owner, with the requested website font/size adjustments and no em dashes. The preview report uses clearly labeled fictional HTML fixtures analyzed by the real metric engine. It does not run a new crawl or access your account. Authentication, real jobs and payment buttons require the server; they are intentionally not active in this standalone review.</p><p class="muted">The separate local live preview includes the existing website’s main navigation. This self-contained file includes the product page and interactive sample dashboard so it can be viewed without external resources.</p><p class="muted">No Netlify deployment, paid upgrade or Stripe activation was performed.</p></main></html>'''
data=json.dumps({'landing':landing,'tool':tool,'status':status}).replace('</',r'<\/')
out='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AEOGEO  -  local product review</title><style>*{box-sizing:border-box}body{margin:0;background:#050b1f;color:white;font-family:system-ui,sans-serif}header{height:64px;display:flex;align-items:center;justify-content:space-between;padding:10px 20px;border-bottom:1px solid #233756;gap:12px}strong{font-size:14px}small{display:block;color:#9bb1d3;font-size:11px;margin-top:3px}nav{display:flex;gap:7px}button{background:#0e1e3b;color:#c3d6f5;border:1px solid #2a4268;padding:9px 15px;border-radius:20px;cursor:pointer;font-weight:600}button[aria-pressed=true]{background:#4f7df9;color:white}iframe{border:0;width:100%;height:calc(100vh - 64px);display:block;background:#050b1f}@media(max-width:600px){header{height:104px;flex-wrap:wrap;padding:10px 15px}iframe{height:calc(100vh - 104px)}button{font-size:11px;padding:8px 12px}}</style></head><body><header><div><strong>AEOGEO / Product Review</strong><small>Local build · no deployment · no payments</small></div><nav aria-label="Review screens"><button data-view="landing" aria-pressed="true">Product page</button><button data-view="tool" aria-pressed="false">Audit dashboard</button><button data-view="status" aria-pressed="false">What’s ready</button></nav></header><iframe id="screen" title="Interactive AEOGEO product review" sandbox="allow-scripts allow-downloads allow-modals"></iframe><script id="views" type="application/json">'''+data+'''</script><script>const views=JSON.parse(document.getElementById('views').textContent),frame=document.getElementById('screen');function show(key){if(!views[key])return;frame.srcdoc=views[key];document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===key)));}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));window.addEventListener('message',e=>{if(e.source===frame.contentWindow&&e.data?.review)show(e.data.review);});show('landing');</script></body></html>'''
(root.parent/'aeogeo-product-review.html').write_text(out)
print('Built self-contained review: aeogeo-product-review.html')
